using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoundSpaceBackend.Services.User.Abstractions;

namespace SoundSpaceBackend.Controllers.Vault;

/// <summary>
/// Serves the user's E2EE private key from server-side configuration.
/// The private key is stored as an environment variable and returned
/// only to the authenticated user who owns it.
/// </summary>
[ApiController]
[Route("api/vault")]
[Authorize]
public class VaultController(
    IUserService userService,
    IConfiguration configuration,
    ILogger<VaultController> logger) : ControllerBase
{
    /// <summary>
    /// GET /api/vault/key
    /// Returns the authenticated user's ECDH private key (base64 PKCS#8)
    /// from the server configuration / environment variable.
    ///
    /// The env var naming convention: E2EE_PRIVATE_KEY_{userId}
    /// For a simpler setup, a single shared key can be used: E2EE_PRIVATE_KEY
    /// </summary>
    [HttpGet("key")]
    public async Task<IActionResult> GetPrivateKey()
    {
        var spotifyId = User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (spotifyId == null)
        {
            logger.LogWarning("[Vault] Spotify ID claim is missing in the token");
            return Unauthorized();
        }

        var user = await userService.GetUserEntityBySpotifyIdAsync(spotifyId);
        if (user is null) return Unauthorized();

        var privateKey = user.PrivateKey;
        if (string.IsNullOrEmpty(privateKey))
        {
            // Try user-specific key first, then fall back to a shared key.
            privateKey = configuration[$"E2EE:PrivateKeys:{user.Id}"]
                      ?? configuration["E2EE:PrivateKey"];
        }

        if (string.IsNullOrEmpty(privateKey))
        {
            logger.LogWarning("[Vault] No E2EE private key configured for user {UserId}", user.Id);
            return NotFound(new { error = "Private key not configured." });
        }

        return Ok(new { privateKey });
    }

    [HttpPost("key")]
    public async Task<IActionResult> StorePrivateKey([FromBody] StorePrivateKeyRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.PrivateKey))
        {
            return BadRequest(new { error = "Private key is required." });
        }

        var spotifyId = User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (spotifyId == null)
        {
            logger.LogWarning("[Vault] Spotify ID claim is missing in the token");
            return Unauthorized();
        }

        var user = await userService.GetUserEntityBySpotifyIdAsync(spotifyId);
        if (user is null) return Unauthorized();

        await userService.StorePrivateKeyAsync(user, request.PrivateKey);
        return NoContent();
    }

    public sealed record StorePrivateKeyRequest(string PrivateKey);
}

using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using SoundSpaceBackend.Services.User.Abstractions;
using SoundSpaceBackend.Services.Vault.Abstractions;

namespace SoundSpaceBackend.Controllers.Vault;

/// <summary>
/// Serves the user's E2EE private key from server-side configuration.
/// The private key is stored as an environment variable and returned
/// only to the authenticated user who owns it.
/// </summary>
[ApiController]
[Route("api/vault")]
[Authorize]
public class VaultController(
    IUserService userService,
    IVaultCryptoService vaultCryptoService,
    ILogger<VaultController> logger) : ControllerBase
{
    /// <summary>
    /// GET /api/vault/key
    /// Returns the authenticated user's ECDH private key (base64 PKCS#8)
    /// from the server configuration / environment variable.
    ///
    /// The env var naming convention: E2EE_PRIVATE_KEY_{userId}
    /// For a simpler setup, a single shared key can be used: E2EE_PRIVATE_KEY
    /// </summary>
    [HttpGet("key")]
    public async Task<IActionResult> GetPrivateKey()
    {
        var spotifyId = User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (spotifyId == null)
        {
            logger.LogWarning("[Vault] Spotify ID claim is missing in the token");
            return Unauthorized();
        }

        var user = await userService.GetUserEntityBySpotifyIdAsync(spotifyId);
        if (user is null) return Unauthorized();

        if (string.IsNullOrWhiteSpace(user.PrivateKeyCiphertext) ||
            string.IsNullOrWhiteSpace(user.PrivateKeyIv) ||
            user.PrivateKeyKeyVersion is null)
        {
            logger.LogWarning("[Vault] No encrypted private key configured for user {UserId}", user.Id);
            return NotFound(new { error = "Private key not configured." });
        }

        var payload = new EncryptedVaultPayload(
            user.PrivateKeyCiphertext,
            user.PrivateKeyIv,
            user.PrivateKeyKeyVersion.Value);

        var privateKey = vaultCryptoService.Decrypt(payload);
        return Ok(new { privateKey });
    }

    [HttpPost("key")]
    public async Task<IActionResult> StorePrivateKey([FromBody] StorePrivateKeyRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.PrivateKey))
        {
            return BadRequest(new { error = "Private key is required." });
        }

        var spotifyId = User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (spotifyId == null)
        {
            logger.LogWarning("[Vault] Spotify ID claim is missing in the token");
            return Unauthorized();
        }

        var user = await userService.GetUserEntityBySpotifyIdAsync(spotifyId);
        if (user is null) return Unauthorized();

        var encrypted = vaultCryptoService.Encrypt(request.PrivateKey);
        await userService.StorePrivateKeyAsync(user, encrypted.Ciphertext, encrypted.Iv, encrypted.KeyVersion);
        return NoContent();
    }

    public sealed record StorePrivateKeyRequest(string PrivateKey);
}

