namespace SoundSpaceBackend.Services.Vault;

public interface IVaultCryptoService
{
    int CurrentKeyVersion { get; }
    EncryptedVaultPayload Encrypt(string plaintext);
    string Decrypt(EncryptedVaultPayload payload);
}

public sealed record EncryptedVaultPayload(string Ciphertext, string Iv, int KeyVersion);

using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Configuration;

namespace SoundSpaceBackend.Services.Vault;

public sealed class VaultCryptoService : IVaultCryptoService
{
    private const int IvSizeBytes = 12;
    private const int TagSizeBytes = 16;
    private readonly byte[] _masterKey;

    public VaultCryptoService(IConfiguration configuration)
    {
        var keyBase64 = configuration["Vault:MasterKey"];
        if (string.IsNullOrWhiteSpace(keyBase64))
        {
            throw new InvalidOperationException("Vault master key is not configured.");
        }

        _masterKey = Convert.FromBase64String(keyBase64);
        if (_masterKey.Length != 32)
        {
            throw new InvalidOperationException("Vault master key must be 32 bytes (base64-encoded)." );
        }
    }

    public int CurrentKeyVersion => 1;

    public EncryptedVaultPayload Encrypt(string plaintext)
    {
        var iv = RandomNumberGenerator.GetBytes(IvSizeBytes);
        var plaintextBytes = Encoding.UTF8.GetBytes(plaintext);
        var ciphertext = new byte[plaintextBytes.Length];
        var tag = new byte[TagSizeBytes];

        using (var aes = new AesGcm(_masterKey, TagSizeBytes))
        {
            aes.Encrypt(iv, plaintextBytes, ciphertext, tag);
        }

        var combined = new byte[ciphertext.Length + tag.Length];
        Buffer.BlockCopy(ciphertext, 0, combined, 0, ciphertext.Length);
        Buffer.BlockCopy(tag, 0, combined, ciphertext.Length, tag.Length);

        return new EncryptedVaultPayload(
            Convert.ToBase64String(combined),
            Convert.ToBase64String(iv),
            CurrentKeyVersion);
    }

    public string Decrypt(EncryptedVaultPayload payload)
    {
        var combined = Convert.FromBase64String(payload.Ciphertext);
        if (combined.Length < TagSizeBytes)
        {
            throw new InvalidOperationException("Vault payload is invalid.");
        }

        var iv = Convert.FromBase64String(payload.Iv);
        var ciphertextLength = combined.Length - TagSizeBytes;
        var ciphertext = new byte[ciphertextLength];
        var tag = new byte[TagSizeBytes];

        Buffer.BlockCopy(combined, 0, ciphertext, 0, ciphertextLength);
        Buffer.BlockCopy(combined, ciphertextLength, tag, 0, TagSizeBytes);

        var plaintext = new byte[ciphertextLength];
        using (var aes = new AesGcm(_masterKey, TagSizeBytes))
        {
            aes.Decrypt(iv, ciphertext, tag, plaintext);
        }

        return Encoding.UTF8.GetString(plaintext);
    }
}
